def read_age(prompt):
    while True:
        try:
            age = int(input(prompt))
        except ValueError:
            print("Please enter a whole number.")
            continue
        if 0 <= age <= 120:
            return age
        print("Please enter an age from 0 to 120.")

age = read_age("Age? ")
